async function uploadFile(file,target=2400,folder='Site assets'){let blob=file;if(file.type.startsWith('image/')&&file.type!=='image/svg+xml'){const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');const size=imageSize(bitmap.width,bitmap.height,target);canvas.width=size.width;canvas.height=size.height;canvas.getContext('2d').drawImage(bitmap,0,0,size.width,size.height);blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84));if(!blob)throw Error('Could not process this image.');}finally{bitmap.close();}}if(blob.size>4*1024*1024)throw Error('This file exceeds the 4 MB upload limit. Use a smaller image or compress the file before uploading.');const name=blob.type==='image/webp'?file.name.replace(/\.[^.]+$/,'')+'.webp':file.name;const r=await fetch('/api/studio/upload',{method:'POST',headers:{'Content-Type':blob.type,'X-File-Name':encodeURIComponent(name),'X-Media-Folder':encodeURIComponent(folder)},body:blob});const data=await r.json();if(!r.ok)throw Error(data.error);return data.item;}

