function AssetField({label,value,onChange,onUpload,onPick,disabled=false,target=2400,ratio,alt,onAlt,fit,onFit}){const input=useRef(null);const [dimensions,setDimensions]=useState(null),[failed,setFailed]=useState(false);useEffect(()=>{setDimensions(null);setFailed(false);},[value]);return <div className="cms-asset-field"><strong>{label}</strong><div className="cms-asset-preview">{value?<img key={value} src={value} alt={label+' preview'} onLoad={e=>setDimensions({width:e.currentTarget.naturalWidth,height:e.currentTarget.naturalHeight})} onError={()=>setFailed(true)}/>:<div><ImageIcon size={25}/><span>No image selected</span></div>}</div><small className="cms-image-spec" aria-live="polite">{failed?'Image could not load. Replace it or check its URL.':dimensions?`${dimensions.width} × ${dimensions.height} px`:'No dimensions available'}{ratio&&` · Recommended ${ratio}`}<br/>Uploads: WebP, up to {target} px on the longest side. No upscaling or cropping. Maximum upload: 4 MB.</small><div className="cms-actions"><button type="button" disabled={disabled} onClick={()=>input.current?.click()}><Upload size={15}/> {disabled?'Working…':value?'Replace':'Upload'}</button><input ref={input} type="file" accept="image/*" disabled={disabled} aria-label={'Upload '+label} onChange={e=>{const file=e.target.files[0];e.target.value='';if(file)onUpload(file,target);}}/><button disabled={disabled} onClick={onPick}>Choose existing</button>{value&&<button disabled={disabled} onClick={()=>onChange('')}>Clear</button>}</div>{onFit&&<ImageFit value={fit} onChange={onFit}/>} {onAlt&&<Field label="Image description" value={alt} onChange={onAlt} help="Describe what matters in this image for someone who cannot see it."/>}<details><summary>Image URL</summary><input disabled={disabled} aria-label={label+' URL'} value={value||''} onChange={e=>onChange(e.target.value)} placeholder="/api/media/… or https://…"/></details></div>}


function Connections({state,refresh,notify,onError}){const [name,setName]=useState('My AI assistant'),[publish,setPublish]=useState(false),[token,setToken]=useState(''),[siteAccess,setSiteAccess]=useState(false),[settingsAccess,setSettingsAccess]=useState(false),[busy,setBusy]=useState(false);const endpoint=window.location.origin+'/mcp';return <><Title eyebrow="CONTENT WITHOUT CODE CHANGES" title="Bring your AI assistant" description="A direct, controlled connection to your content. No Git access. No deploy for each new story."/><div className="cms-overview-grid"><section className="cms-panel cms-form"><h2>Connect through MCP</h2><p>Use a client that supports Streamable HTTP and a Bearer token, such as Codex. Tokens expire after 90 days and can be revoked at any time.</p><Field label="Server URL" value={endpoint} readOnly onChange={()=>{}}/><ol className="cms-connection-steps"><li>Create a named token below.</li><li>Add this server URL in your AI client's MCP settings.</li><li>Set its Authorization header to <code>Bearer YOUR_TOKEN</code>, or select its bearer-token environment variable option.</li><li>Ask the assistant to create a draft, upload assets and show you the preview.</li></ol><details><summary>Example instruction for your assistant</summary><p>Read cms_schema, cms_editorial_standard, cms_presentation_guide and cms_media_architecture. List existing projects first. Create the draft before uploading; its Projects/&lt;slug&gt; folder is automatic. Upload named images to that exact folder, then save native text, image and grid blocks with cms_save using the latest cms_get version. Set discipline, industry and brandPersonality. Verify benchmark pages and record exact URLs and dates. Run cms_review and inspect desktop and mobile. Keep as draft unless I request publication; then use cms_publish with the current version. Never modify site code or invent client claims.</p></details><p className="cms-subtle">This endpoint uses personal access tokens. OAuth-only clients are not supported by this version.</p></section><section className="cms-panel cms-form"><h2>Create an access token</h2><Field label="Connection name" value={name} onChange={setName}/><label className="cms-check"><input type="checkbox" checked={publish} onChange={e=>setPublish(e.target.checked)}/> Allow publishing to the live site</label><label className="cms-check"><input type="checkbox" checked={siteAccess} onChange={e=>setSiteAccess(e.target.checked)}/> Allow editing pages and navigation</label><label className="cms-check"><input type="checkbox" checked={settingsAccess} onChange={e=>setSettingsAccess(e.target.checked)}/> Allow editing public site settings</label><p>{publish?'This assistant can publish individual documents when you instruct it.':'This assistant can read, upload and save drafts. Publishing stays in your hands.'}</p><button className="cms-primary" disabled={busy||!name.trim()} onClick={async()=>{setBusy(true);try{const r=await api('/api/cms/keys',{name,publish,site:siteAccess,settings:settingsAccess});setToken(r.token);refresh();}catch(e){onError(e);}finally{setBusy(false);}}}><Plug size={17}/> Create token</button>{token&&<div className="cms-token"><strong>Copy now. Shown only once.</strong><textarea aria-label="New access token" readOnly value={token}/><button onClick={async()=>{try{await navigator.clipboard.writeText(token);notify('Token copied. Store it in your AI client, not in source code.');}catch{onError(Error('Select and copy the token manually.'));}}}>Copy token</button><button onClick={()=>setToken('')}>Hide token</button></div>}</section></div><section className="cms-panel cms-form"><h2>Your connections</h2>{state.keys.length?state.keys.map(k=><div className="cms-revision" key={k.id}><div><strong>{k.name}</strong><small>{k.scopes.join(' · ')} · expires {date(k.expiresAt)} {k.revokedAt?'· Revoked':''}</small></div><button disabled={!!k.revokedAt} onClick={async()=>{try{await api('/api/cms/keys',{action:'revoke',id:k.id});refresh();notify('Connection revoked.');}catch(e){onError(e);}}}>Revoke</button></div>):<p>No AI connections yet.</p>}</section></>}
function StudioSettings({state,refresh,notify,onError}){const [settings,setSettings]=useState(state.settings);async function save(publish){try{await api('/api/cms/settings',{settings,draftVersion:state.draftVersion,publish});await refresh();notify(publish?'Site settings published. Other drafts remain private.':'Settings draft saved.');}catch(e){onError(e);}}return <><Title eyebrow="THE FINISHING DETAILS" title="Site settings" description="Identity and owner access, in one place."/><SettingsPanel value={settings} onChange={setSettings}/><div className="cms-actions"><button onClick={()=>save(false)}>Save settings draft</button><button className="cms-primary" onClick={()=>save(true)}>Publish these settings</button></div></>}

function GridPicker({value,onChange}){return <fieldset className="cms-grid-picker"><legend>Choose the visual rhythm</legend><details><summary>Layout {String(value).padStart(2,"0")} · {composition(value).boxes.length} images — change layout</summary><div>{Array.from({length:20},(_,i)=>{const layout=composition(i+1);return <button type="button" key={i} className={value===i+1?"active":""} aria-label={"Layout "+(i+1)+", "+layout.boxes.length+" images"} aria-pressed={value===i+1} onClick={()=>onChange(i+1)}><svg viewBox={`0 0 ${layout.width} ${layout.height}`} aria-hidden="true">{layout.boxes.map((b,j)=><rect key={j} x={b.x} y={b.y} width={b.w} height={b.h} rx="12"/>)}</svg><span>{String(i+1).padStart(2,"0")} · {layout.boxes.length} images</span></button>})}</div></details></fieldset>}

function NavigationEditor({state,refresh,notify,onError}){const [nav,setNav]=useState(state.nav);function patch(i,value){setNav(nav.map((n,j)=>i===j?{...n,...value}:n));}async function save(publish){try{await api('/api/cms/navigation',{nav,draftVersion:state.draftVersion,publish});refresh();notify(publish?'Navigation published. Content drafts stay private.':'Navigation draft saved.');}catch(e){onError(e);}}return <section className="cms-panel cms-form"><h2>Site navigation</h2><p>Choose the labels, destinations and order of your menu.</p>{nav.map((n,i)=><div className="cms-nav-row" key={n.id}><Field label="Label" value={n.label} onChange={label=>patch(i,{label})}/><Field label="Destination" value={n.to||n.url} onChange={to=>patch(i,{to})}/><label className="cms-check"><input type="checkbox" checked={n.visible!==false} onChange={e=>patch(i,{visible:e.target.checked})}/>Visible</label><button aria-label={'Move '+n.label+' up'} disabled={!i} onClick={()=>{const next=[...nav];[next[i-1],next[i]]=[next[i],next[i-1]];setNav(next);}}><ChevronUp size={16}/></button><button aria-label={'Remove '+n.label} disabled={['/work','/contact'].includes(n.to||n.url)} title={['/work','/contact'].includes(n.to||n.url)?'This primary route must remain in navigation.':'Remove navigation item'} onClick={()=>setNav(nav.filter((_,j)=>j!==i))}><Trash2 size={16}/></button></div>)}<div className="cms-actions"><button onClick={()=>setNav([...nav,{id:uuid(),label:'New link',to:'/',visible:true}])}>Add link</button><button onClick={()=>save(false)}>Save navigation draft</button><button className="cms-primary" onClick={()=>save(true)}>Publish navigation</button></div></section>}

function ImageFit({value="contain",onChange}){return <label className="cms-field"><span>Image display</span><select value={value} onChange={e=>onChange(e.target.value)}><option value="contain">Fit · show the full image</option></select><small>Content images always show the full image. Only covers use a centred square crop.</small></label>;}
